using System.ComponentModel.DataAnnotations;
using Microsoft.EntityFrameworkCore;
namespace AudioGuide.Data;
public class AdminUser { public int Id { get; set; } [Required(AllowEmptyStrings = true)] public string Username { get; set; } = ""; [Required(AllowEmptyStrings = true)] public string PasswordHash { get; set; } = ""; [Required(AllowEmptyStrings = true)] public string FullName { get; set; } = ""; [Required(AllowEmptyStrings = true)] public string Role { get; set; } = "Editor"; public bool IsActive { get; set; } = true; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class Language { public int Id { get; set; } [Required(AllowEmptyStrings = true)] public string Code { get; set; } = ""; [Required(AllowEmptyStrings = true)] public string Name { get; set; } = ""; [Required(AllowEmptyStrings = true)] public string NativeName { get; set; } = ""; [Required(AllowEmptyStrings = true)] public string TtsVoiceCode { get; set; } = ""; public bool IsDefault { get; set; } public bool IsActive { get; set; } = true; }
public class Location { public int Id { get; set; } [Required(AllowEmptyStrings = true)] public string Slug { get; set; } = ""; public double Latitude { get; set; } public double Longitude { get; set; } public int RadiusM { get; set; } = 60; public int Priority { get; set; } [Required(AllowEmptyStrings = true)] public string ImageUrl { get; set; } = ""; [Required(AllowEmptyStrings = true)] public string OpeningHours { get; set; } = ""; [Required(AllowEmptyStrings = true)] public string Address { get; set; } = ""; public int DisplayOrder { get; set; } public bool IsActive { get; set; } = true; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public DateTime UpdatedAt { get; set; } = DateTime.UtcNow; }
public class LocationTranslation { public int Id { get; set; } public int LocationId { get; set; } public Location Location { get; set; } = null!; public int LanguageId { get; set; } public Language Language { get; set; } = null!; [Required(AllowEmptyStrings = true)] public string Name { get; set; } = ""; [Required(AllowEmptyStrings = true)] public string ShortDescription { get; set; } = ""; [Required(AllowEmptyStrings = true)] public string NarrationText { get; set; } = ""; [Required(AllowEmptyStrings = true)] public string HistoryText { get; set; } = ""; [Required(AllowEmptyStrings = true)] public string Status { get; set; } = "Draft"; public bool IsMachineTranslated { get; set; } public DateTime UpdatedAt { get; set; } = DateTime.UtcNow; }
public class AudioNarration { public int Id { get; set; } public int TranslationId { get; set; } public LocationTranslation Translation { get; set; } = null!; [Required(AllowEmptyStrings = true)] public string FileUrl { get; set; } = ""; public double DurationSec { get; set; } [Required(AllowEmptyStrings = true)] public string Source { get; set; } = "Upload"; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class PlayLog { public long Id { get; set; } [Required(AllowEmptyStrings = true)] public string SessionId { get; set; } = ""; public int LocationId { get; set; } public Location Location { get; set; } = null!; public int LanguageId { get; set; } public Language Language { get; set; } = null!; [Required(AllowEmptyStrings = true)] public string TriggerType { get; set; } = "Manual"; public bool Completed { get; set; } public DateTime PlayedAt { get; set; } = DateTime.UtcNow; }
public class Feedback { public long Id { get; set; } public int LocationId { get; set; } public Location Location { get; set; } = null!; public int LanguageId { get; set; } public Language Language { get; set; } = null!; public int Rating { get; set; } [Required(AllowEmptyStrings = true)] public string Comment { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class AuditLog { public long Id { get; set; } [Required(AllowEmptyStrings = true)] public string Username { get; set; } = ""; [Required(AllowEmptyStrings = true)] public string Action { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
    public DbSet<AdminUser> AdminUsers => Set<AdminUser>(); public DbSet<Language> Languages => Set<Language>(); public DbSet<Location> Locations => Set<Location>(); public DbSet<LocationTranslation> Translations => Set<LocationTranslation>(); public DbSet<AudioNarration> Audios => Set<AudioNarration>(); public DbSet<PlayLog> PlayLogs => Set<PlayLog>(); public DbSet<Feedback> Feedbacks => Set<Feedback>(); public DbSet<AuditLog> AuditLogs => Set<AuditLog>();
    protected override void OnModelCreating(ModelBuilder m)
    {
        m.HasCharSet("utf8mb4").UseCollation("utf8mb4_unicode_ci");
        m.Entity<AdminUser>().HasIndex(x => x.Username).IsUnique(); m.Entity<AdminUser>().Property(x => x.Username).HasMaxLength(100);
        m.Entity<Language>().HasIndex(x => x.Code).IsUnique(); m.Entity<Language>().Property(x => x.Code).HasMaxLength(20);
        m.Entity<Location>().HasIndex(x => x.Slug).IsUnique(); m.Entity<Location>().Property(x => x.Slug).HasMaxLength(150); m.Entity<Location>().HasIndex(x => new { x.IsActive, x.DisplayOrder }); m.Entity<Location>().Property(x => x.Latitude).HasColumnType("decimal(9,6)"); m.Entity<Location>().Property(x => x.Longitude).HasColumnType("decimal(9,6)");
        m.Entity<LocationTranslation>().HasIndex(x => new { x.LocationId, x.LanguageId }).IsUnique(); m.Entity<AudioNarration>().HasIndex(x => x.TranslationId).IsUnique(); m.Entity<PlayLog>().HasIndex(x => new { x.LocationId, x.PlayedAt }); m.Entity<PlayLog>().Property(x => x.SessionId).HasMaxLength(36);
        var tables = new Dictionary<Type, string> { { typeof(AdminUser), "admin_users" }, { typeof(Language), "languages" }, { typeof(Location), "locations" }, { typeof(LocationTranslation), "location_translations" }, { typeof(AudioNarration), "audio_narrations" }, { typeof(PlayLog), "play_logs" }, { typeof(Feedback), "feedbacks" }, { typeof(AuditLog), "audit_logs" } };
        foreach (var entity in m.Model.GetEntityTypes()) { entity.SetTableName(tables[entity.ClrType]); foreach (var property in entity.GetProperties()) { var name = System.Text.RegularExpressions.Regex.Replace(property.Name, "([a-z0-9])([A-Z])", "$1_$2").ToLowerInvariant(); property.SetColumnName(name); } }
        foreach (var fk in m.Model.GetEntityTypes().SelectMany(x => x.GetForeignKeys())) fk.DeleteBehavior = DeleteBehavior.Restrict;
        m.Entity<AudioNarration>().HasOne(x => x.Translation).WithMany().OnDelete(DeleteBehavior.Cascade);
    }
}
public interface IRepository { AppDbContext Db { get; } Task Save(); }
public class Repository(AppDbContext db) : IRepository { public AppDbContext Db => db; public Task Save() => db.SaveChangesAsync(); }
